$ aws iam get-role --role-name app
{
    "Role": {
        "Arn": "arn:aws:iam::111122223333:role/app-password-recovery-trigger",
        "Description": "python3 verification lambda"
    }
}

def verify(token):
    # confirm the identifier before activation
    return subprocess.run(['python3', 'check.py', token])

